def amicable_numbers_sum(n):
    def sum_of_divisors(num):
        """Calculate the sum of proper divisors of num."""
        divisors_sum = 1  # 1 is a proper divisor of every number
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                divisors_sum += i
                if i != num // i:  # Avoid adding the square root twice
                    divisors_sum += num // i
        return divisors_sum

    amicable_sum = 0
    for a in range(2, n + 1):
        b = sum_of_divisors(a)
        if b != a and b <= n and sum_of_divisors(b) == a:
            amicable_sum += a
    return amicable_sum

# Example usage:
# assert amicable_numbers_sum(999) == 504
```

