def maximize_elements(tuple1, tuple2):
    """
    Takes two tuples of tuples and returns a new tuple where each
    element is the maximum values at corresponding positions in the input tuples.
    """
    # Ensure both inputs are of the same length
    if len(tuple1) != len(tuple2):
        raise ValueError("Both input tuples must have the same length.")

    # Use a generator to iterate through both tuples and maximize each pair
    return tuple(
        (max(a1, b1), max(a2, b2))
        for (a1, a2), (b1, b2) in zip(tuple1, tuple2)
    )

# Example usage and test
assert maximize_elements(
    ((1, 3), (4, 5), (2, 9), (1, 10)),
    ((6, 7), (3, 9), (1, 1), (7, 3))
) == ((6, 7), (4, 9), (2, 9), (7, 10))
```

