def start_withp(word_list):
    words_starting_with_p = []
    for phrase in word_list:
        words = phrase.split()
        for word in words:
            if word.startswith('P'):
                words_starting_with_p.append(word)
                if len(words_starting_with_p) == 2:
                    return tuple(words_starting_with_p)
    return tuple(words_starting_with_p)

