assert start_withp(["Perl Python", "PHP Ruby", "Pascal"]) == ('Perl', 'Python')
assert start_withp(["Java JavaScript", "c c++"]) == ()
assert start_withp(["Python", "PHP"]) == ('Python', 'PHP')
