def find_kth(arr1, arr2, k):
    def kth_element(a, b, k):
        if not a:  # If one array is empty, return the k-th element of the other
            return b[k-1]
        if not b:
            return a[k-1]
        if k == 1:  # Base case: if k == 1, return the smallest of the two arrays' first elements
            return min(a[0], b[0])

        # Divide and conquer: Compare the middle elements of two arrays
        idx_a = min(len(a), k // 2) - 1
        idx_b = min(len(b), k // 2) - 1
        mid_a, mid_b = a[idx_a], b[idx_b]

        # Discard half of one array based on comparison
        if mid_a <= mid_b:
            return kth_element(a[idx_a + 1:], b, k - (idx_a + 1))
        else:
            return kth_element(a, b[idx_b + 1:], k - (idx_b + 1))

    return kth_element(arr1, arr2, k)

# Example usage and test
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
