def count_Substrings(s):
    def digit_sum(substr):
        return sum(int(d) for d in substr)

    count = 0
    n = len(s)

    for i in range(n):
        for j in range(i + 1, n + 1):
            substr = s[i:j]
            if digit_sum(substr) == len(substr):
                count += 1

    return count

# Test case
assert count_Substrings('112112') == 6
