def tuple_to_dict(tup):
    """
    Convert a given tuple into a dictionary using adjacent elements as key-value pairs.
    """
    if len(tup) % 2 != 0:
        raise ValueError("Tuple must have an even number of elements to form key-value pairs.")

    return {tup[i]: tup[i + 1] for i in range(0, len(tup), 2)}

# Example usage and test cases
assert tuple_to_dict((1, 5, 7, 10, 13, 5)) == {1: 5, 7: 10, 13: 5}
```

